import React from "react";
import { useState, useRef, useEffect } from "react";
import Modal from "react-bootstrap/Modal";
import AudioPlayer from "./AudioPlayer";
import asset from "../asset/asset";
import { Button } from "@mui/material";
//imports for audio instuctions

import audio_instr_2 from "../audio/SawASeed/audio_instr_2.mp3";
import audio_instr_1 from "../audio/SawASeed/audio_instr_1.mp3";
import audio_instr_3 from "../audio/SawASeed/audio_instr_3.mp3";
import audio_instr_4 from "../audio/SawASeed/audio_instr_4.mp3";
import audio_instr_5 from "../audio/SawASeed/audio_inst_5.mp3";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { toast } from "react-toastify";

const SawASeedMidContent_copy = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const canvasRef = useRef(null);
  const [imagesLoaded, setImagesLoaded] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [compareModal, setCompareModal] = useState(false);

  const [draggableImages, setDraggableImages] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const bgImgRef = useRef(null);
  const objectBoxRef = useRef(null);

  const draggingRef = useRef(false);
  const dragOffsetRef = useRef({ x: 0, y: 0 });
  const draggedImageRef = useRef(null);
  const objectBoxBoundsRef = useRef(null);
  const [activeObjects, setActiveObjects] = useState([]);
  const [capturedImageURL, setCapturedImageURL] = useState(null);
  const [isHoveringObjectBox, setIsHoveringObjectBox] = useState(false);

  const [isNextDisabled, setIsNextDisabled] = useState(true);

  // Define regions (for positions)
  const regions = {
    table: {
      x: 0.5,
      y: 0.1,
      width: 0.4,
      height: 0.3,
      isLocked: false,
    },
    pot: {
      x: 0.5,
      y: 0.1,
      width: 0.2,
      height: 0.25,
      isLocked: false,
    },
    seed: {
      x: 0.5,
      y: 0.1,
      width: 0.05,
      height: 0.1,
      isLocked: false,
    },
    sprayer: {
      x: 0.5,
      y: 0.1,
      width: 0.2,
      height: 0.3,
      isLocked: false,
    },
  };

  // Calculate absolute position and size while maintaining aspect ratio
  const getImageDimensions = (image, canvas) => {
    if (!canvas || !image.originalWidth || !image.originalHeight) {
      return { x: 0, y: 0, width: 0, height: 0 };
    }

    const aspectRatio = image.originalHeight / image.originalWidth;
    const targetWidth = canvas.width * image.position.width;
    const targetHeight = targetWidth * aspectRatio;

    return {
      x: image.position.x * canvas.width,
      y: image.position.y * canvas.height,
      width: targetWidth,
      height: targetHeight,
    };
  };

  // Load all the images
  const loadImages = () => {
    const imageKeys = Object.keys(regions);
    const loadedImages = [];

    imageKeys.forEach((key) => {
      const img = new Image();
      img.src = asset[key];
      img.onload = () => {
        loadedImages.push({
          name: key,
          img: img,
          region: regions[key],
          isActive: false,
          locked: false,
          position: { ...regions[key] },
          originalWidth: img.width,
          originalHeight: img.height,
        });

        if (loadedImages.length === imageKeys.length) {
          setDraggableImages(loadedImages);
          setImagesLoaded(true);
        }
      };
    });
  };

  useEffect(() => {
    loadImages();
  }, []);

  useEffect(() => {
    if (imagesLoaded) {
      draw();
    }
  }, [imagesLoaded, activeObjects, draggableImages]);

  const draw = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    if (!canvas || !ctx) return;

    const objectImg = objectBoxRef.current;
    const bg = bgImgRef.current;

    if (!objectImg || !bg) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(bg, 0, 0, canvas.width, canvas.height);

    const objectImgSize = Math.min(canvas.width, canvas.height) * 0.15;
    const objectX = 5;
    const objectY = 5;
    ctx.drawImage(objectImg, objectX, objectY, objectImgSize, objectImgSize);

    objectBoxBoundsRef.current = {
      x: objectX,
      y: objectY,
      width: objectImgSize,
      height: objectImgSize,
    };

    // Draw only active draggable images
    draggableImages.forEach((image) => {
      if (image.isActive) {
        const box = getImageDimensions(image, canvas);
        ctx.globalAlpha = image.locked ? 0.9 : 1; // semi-transparent if locked
        ctx.drawImage(image.img, box.x, box.y, box.width, box.height);
        ctx.globalAlpha = 1;
      }
    });
  };

  // Resize the canvas on window resize
  useEffect(() => {
    if (!imagesLoaded) return;

    const canvas = canvasRef.current;
    const resizeCanvas = () => {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = rect.height;
      draw();
    };

    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();

    return () => window.removeEventListener("resize", resizeCanvas);
  }, [imagesLoaded]);

  const getMousePos = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    };
  };

  const onStart = (e) => {
    e.preventDefault();

    if (e.touches && e.touches.length > 0) {
      const touch = e.touches[0];
      handleStart(touch.clientX, touch.clientY);
    } else {
      handleStart(e.clientX, e.clientY);
    }
  };

  const onMove = (e) => {
    if (!draggingRef.current || !draggedImageRef.current) return;

    e.preventDefault();

    let clientX, clientY;

    if (e.touches && e.touches.length > 0) {
      const touch = e.touches[0];
      clientX = touch.clientX;
      clientY = touch.clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }

    const pos = getMousePosFromCoords(clientX, clientY);
    const image = draggedImageRef.current;
    const canvas = canvasRef.current;

    // Update position
    image.position.x = (pos.x - dragOffsetRef.current.x) / canvas.width;
    image.position.y = (pos.y - dragOffsetRef.current.y) / canvas.height;

    // Update the draggableImages state
    setDraggableImages((prev) => [...prev]); // Trigger re-render

    draw();
  };

  const onEnd = () => {
    draggingRef.current = false;

    if (draggedImageRef.current) {
      const image = draggedImageRef.current;
      const canvas = canvasRef.current;

      // Get table image from draggableImages
      const tableImage = draggableImages.find((img) => img.name === "table");
      if (!tableImage) {
        draggedImageRef.current = null;
        draw();
        return;
      }

      // Get pot image from draggableImages
      const potImage = draggableImages.find((img) => img.name === "pot");
      if (!potImage) {
        draggedImageRef.current = null;
        draw();
        return;
      }

      // Get seed image from draggableImages
      const seedImage = draggableImages.find((img) => img.name === "seed");
      if (!seedImage) {
        draggedImageRef.current = null;
        draw();
        return;
      }

      // Get sprayer image from draggableImages
      const sprayerImage = draggableImages.find(
        (img) => img.name === "sprayer"
      );
      if (!seedImage) {
        draggedImageRef.current = null;
        draw();
        return;
      }

      // Calculate absolute positions & sizes in pixels
      const tableX = tableImage.position.x * canvas.width;
      const tableY = tableImage.position.y * canvas.height;
      const tableWidth = tableImage.position.width * canvas.width;

      const potX = potImage.position.x * canvas.width;
      const potY = potImage.position.y * canvas.height;
      const potWidth = potImage.position.width * canvas.width;
      // const potHeight = potImage.position.height * canvas.height;

      const seedX = seedImage.position.x * canvas.width;
      const seedY = seedImage.position.y * canvas.height;
      const seedWidth = seedImage.position.width * canvas.width;

      const sprayerX = sprayerImage.position.x * canvas.width;
      const sprayerY = sprayerImage.position.y * canvas.height;
      // const sprayerHeight = sprayerImage.position.height * canvas.height;

      if (image.name === "table") {
        // Your existing table locking logic
        if (
          tableY > canvas.height / 2 &&
          tableY < canvas.height &&
          tableX > canvas.width / 9 &&
          tableX < canvas.width / 3
        ) {
          setDraggableImages((prevImages) =>
            prevImages.map((img) =>
              img.name === "table"
                ? { ...img, locked: true, position: { ...image.position } }
                : img
            )
          );
          toast.success("Great job! You placed table at correct position.", {
            position: "top-center",
            autoClose: 2000,
          });
          setIsNextDisabled(false);
        }
      } else if (image.name === "pot") {
        const isWithinX = potX > tableX && potX < tableX + tableWidth;
        const isPotBottomNearTableTop = Math.abs(potY - tableY) <= 30;

        if (isWithinX && isPotBottomNearTableTop) {
          // Lock pot and fix position
          setDraggableImages((prevImages) =>
            prevImages.map((img) =>
              img.name === "pot"
                ? { ...img, locked: true, position: { ...image.position } }
                : img
            )
          );
          toast.success("Great job! You placed pot at correct position.", {
            position: "top-center",
            autoClose: 2000,
          });
          setIsNextDisabled(false);
        }
      } else if (image.name === "seed") {
        const isWithinX = seedX > potX && seedX + seedWidth < potX + potWidth;
        const isSeedBottomNearPotTop = Math.abs(seedY - potY) <= 30;

        if (isWithinX && isSeedBottomNearPotTop) {
          // Lock pot and fix position
          setDraggableImages((prevImages) =>
            prevImages.map((img) =>
              img.name === "seed"
                ? { ...img, locked: true, position: { ...image.position } }
                : img
            )
          );
          toast.success("Great job! You placed seed at correct position.", {
            position: "top-center",
            autoClose: 2000,
          });
          setIsNextDisabled(false);
        }
      } else {
        const isWithinX = sprayerX > potX && sprayerX < potX + potWidth;
        const ratio = potY / sprayerY;
        const isSprayerAbovePot = ratio >= 1.8 && ratio <= 2.2;

        if (isWithinX && isSprayerAbovePot) {
          // Lock pot and fix position
          setDraggableImages((prevImages) =>
            prevImages.map((img) =>
              img.name === "sprayer"
                ? { ...img, locked: true, position: { ...image.position } }
                : img
            )
          );
          toast.success("Great job! You placed sprayer at correct position.", {
            position: "top-center",
            autoClose: 2000,
          });
          setIsNextDisabled(false);
        }
      }
    }

    draggedImageRef.current = null;
    draw();
  };

  const onHover = (e) => {
    const pos = getMousePos(e);

    // Check object box hover
    const objectBoxHover =
      objectBoxBoundsRef.current &&
      pos.x >= objectBoxBoundsRef.current.x &&
      pos.x <=
        objectBoxBoundsRef.current.x + objectBoxBoundsRef.current.width &&
      pos.y >= objectBoxBoundsRef.current.y &&
      pos.y <= objectBoxBoundsRef.current.y + objectBoxBoundsRef.current.height;

    setIsHoveringObjectBox(objectBoxHover);

    // Update canvas cursor style
    if (objectBoxHover) {
      canvasRef.current.style.cursor = "pointer";
    } else {
      canvasRef.current.style.cursor = "default";
    }
  };

  const onMouseLeave = () => {
    setIsHoveringObjectBox(false);
    canvasRef.current.style.cursor = "default";
  };

  const handleStart = (x, y) => {
    const pos = getMousePosFromCoords(x, y);

    // Check if objectBox (top-left icon) was tapped/clicked
    if (
      objectBoxBoundsRef.current &&
      pos.x >= objectBoxBoundsRef.current.x &&
      pos.x <=
        objectBoxBoundsRef.current.x + objectBoxBoundsRef.current.width &&
      pos.y >= objectBoxBoundsRef.current.y &&
      pos.y <= objectBoxBoundsRef.current.y + objectBoxBoundsRef.current.height
    ) {
      setShowModal(true);
      return;
    }

    // Check if any draggable image was tapped/clicked for dragging
    const canvas = canvasRef.current;

    for (const image of draggableImages) {
      if (image.isActive && !image.locked) {
        const box = getImageDimensions(image, canvas);

        if (
          pos.x >= box.x &&
          pos.x <= box.x + box.width &&
          pos.y >= box.y &&
          pos.y <= box.y + box.height
        ) {
          draggingRef.current = true;
          dragOffsetRef.current = {
            x: pos.x - box.x,
            y: pos.y - box.y,
          };
          draggedImageRef.current = image;
          break;
        }
      }
    }
  };

  const getMousePosFromCoords = (clientX, clientY) => {
    const rect = canvasRef.current.getBoundingClientRect();
    return {
      x: clientX - rect.left,
      y: clientY - rect.top,
    };
  };

  // Load all the images
  useEffect(() => {
    const objectImg = new Image();
    const bgImg = new Image();

    let loaded = 0;
    const checkLoaded = () => {
      loaded++;
      if (loaded === 2) {
        objectBoxRef.current = objectImg;
        bgImgRef.current = bgImg;
        setImagesLoaded(true);
      }
    };

    objectImg.onload = checkLoaded;
    bgImg.onload = checkLoaded;

    objectImg.src = asset.objectbox;
    bgImg.src = asset.background;
  }, []);

  useEffect(() => {
    if (!imagesLoaded) return;

    const canvas = canvasRef.current;

    canvas.addEventListener("mousedown", onStart);
    canvas.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onEnd);

    canvas.addEventListener("touchstart", onStart, { passive: false });
    canvas.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onEnd);

    return () => {
      canvas.removeEventListener("mousedown", onStart);
      canvas.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onEnd);

      canvas.removeEventListener("touchstart", onStart);
      canvas.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onEnd);
    };
  }, [imagesLoaded, draggableImages]);

  useEffect(() => {
    if (!imagesLoaded) return;

    const canvas = canvasRef.current;
    canvas.addEventListener("mousemove", onHover);
    canvas.addEventListener("mouseleave", onMouseLeave);

    return () => {
      canvas.removeEventListener("mousemove", onHover);
      canvas.removeEventListener("mouseleave", onMouseLeave);
    };
  }, [imagesLoaded]);

  const handleObjectClick = (objectName) => {
    setDraggableImages((prevImages) =>
      prevImages.map((image) =>
        image.name === objectName ? { ...image, isActive: true } : image
      )
    );

    setActiveObjects((prevActiveObjects) => {
      if (!prevActiveObjects.includes(objectName)) {
        return [...prevActiveObjects, objectName];
      }
      return prevActiveObjects;
    });
    setShowModal(false);
  };

  const handleNext = () => {
    setIsNextDisabled(true);
    if (activeObjects.length !== currentIndex + 1) {
      alert("Please complete the current step!");
    } else {
      setCurrentIndex(currentIndex + 1);
    }
  };

  const handleCompare = () => {
    const canvas = canvasRef.current;
    const imageURL = canvas.toDataURL("image/png");
    setCapturedImageURL(imageURL);
    setCompareModal(true);
  };

  return (
    <div
      className="row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "10px",
          }}
        >
          <canvas
            ref={canvasRef}
            style={{
              width: "100%",
              height: "100%",
              display: "block",
              touchAction: "none",
              border: "1px solid black",
              cursor: isHoveringObjectBox ? "pointer" : "default",
            }}
          />
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div
            style={{
              maxHeight: "50vh",
              padding: "2%",
              lineHeight: "30px",
              fontSize: "calc(.6rem + .4vw)",
            }}
          >
            <div>
              <ul>
                <div>{t("instr1")}</div>
                <div className="fw-bolder text-success text-center">
                  {t("instr2")}
                </div>
                {currentIndex >= 0 && (
                  <div className="row">
                    <div className="col d-flex align-items-center justify-content-center">
                      Step-1:
                    </div>
                    <div className="col">
                      <AudioPlayer src={audio_instr_1} />
                    </div>
                  </div>
                )}

                {currentIndex >= 1 && (
                  <div className="row">
                    <div className="col d-flex align-items-center justify-content-center">
                      Step-2:
                    </div>
                    <div className="col">
                      <AudioPlayer src={audio_instr_2} />
                    </div>
                  </div>
                )}

                {currentIndex >= 2 && (
                  <div className="row">
                    <div className="col d-flex align-items-center justify-content-center">
                      Step-3:
                    </div>
                    <div className="col">
                      <AudioPlayer src={audio_instr_3} />
                    </div>
                  </div>
                )}

                {currentIndex >= 3 && (
                  <div className="row">
                    <div className="col d-flex align-items-center justify-content-center">
                      Step-4:
                    </div>
                    <div className="col">
                      <AudioPlayer src={audio_instr_4} />
                    </div>
                  </div>
                )}

                {currentIndex >= 4 && (
                  <div className="row">
                    <div className="col d-flex align-items-center justify-content-center">
                      Step-5:
                    </div>
                    <div className="col">
                      <AudioPlayer src={audio_instr_5} />
                    </div>
                  </div>
                )}
                <div className="row">
                  <div className="text-center mt-3">
                    {currentIndex !== 4 ? (
                      <Button
                        variant="contained"
                        disabled={isNextDisabled}
                        sx={{
                          background: "#0F477E",
                          fontSize: "calc(.6rem + .4vw)",
                        }}
                        onClick={handleNext}
                      >
                        {t("next")}
                      </Button>
                    ) : (
                      <Button
                        variant="contained"
                        sx={{
                          background: "#0F477E",
                          fontSize: "calc(.6rem + .4vw)",
                        }}
                        onClick={handleCompare}
                        disabled={activeObjects.length !== 4}
                      >
                        {t("finish")}
                      </Button>
                    )}
                  </div>
                </div>
              </ul>
            </div>
          </div>
        </div>
      </div>
      {/* Modal to show images */}
      <Modal
        show={showModal}
        onHide={() => setShowModal(false)}
        size="lg"
        aria-labelledby="example-modal-sizes-title-lg"
      >
        <Modal.Header
          closeButton
          style={{ background: "#90D5FF", fontSize: "calc(.6rem + .4vw)" }}
        >
          <Modal.Title>
            <b>Select an image</b>
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div
            className="image-container"
            style={{ fontSize: "calc(.6rem + .4vw)" }}
          >
            <img
              id="table"
              onClick={
                currentIndex === 0
                  ? () => handleObjectClick("table")
                  : undefined
              }
              src={asset.table}
              alt="table"
              style={{
                opacity: activeObjects.includes("table") ? 0.5 : 1,
                border: currentIndex === 0 ? "1px dotted red" : "none",
                cursor: "pointer",
                padding: "10px",
              }}
            />
            <img
              id="pot"
              onClick={
                currentIndex === 1 ? () => handleObjectClick("pot") : undefined
              }
              src={asset.pot}
              alt="pot"
              style={{
                opacity: activeObjects.includes("pot") ? 0.5 : 1,
                border: currentIndex === 1 ? "1px dotted red" : "none",
                cursor: "pointer",
                padding: "10px",
              }}
            />
            <img
              id="seed"
              onClick={
                currentIndex === 2 ? () => handleObjectClick("seed") : undefined
              }
              src={asset.seed}
              alt="seed"
              style={{
                opacity: activeObjects.includes("seed") ? 0.5 : 1,
                border: currentIndex === 2 ? "1px dotted red" : "none",
                cursor: "pointer",
                padding: "10px",
              }}
            />
            <img
              id="sprayer"
              onClick={
                currentIndex === 3
                  ? () => handleObjectClick("sprayer")
                  : undefined
              }
              src={asset.sprayer}
              alt="sprayer"
              style={{
                opacity: activeObjects.includes("sprayer") ? 0.5 : 1,
                border: currentIndex === 3 ? "1px dotted red" : "none",
                cursor: "pointer",
                padding: "10px",
              }}
            />
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="contained"
            sx={{ fontSize: "calc(.6rem + .2vw)", background: "#0F477E" }}
            onClick={() => setShowModal(false)}
          >
            Close
          </Button>
        </Modal.Footer>
      </Modal>
      {/* Show images modal ends here */}
      {/* compare Modal starts from here */}
      <Modal
        show={compareModal}
        onHide={() => setCompareModal(false)}
        size="lg"
        aria-labelledby="example-modal-sizes-title-lg"
      >
        <Modal.Header
          closeButton
          style={{ background: "#90D5FF", fontSize: "calc(.6rem + .4vw)" }}
        >
          <Modal.Title>
            <b>Conclusion</b>
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div style={{ fontSize: "calc(.6rem + .4vw)" }}>
            <div className="fw-bolder text-center">{t("instr3")}</div>
            <div className="d-flex">
              <div className="col text-center me-2">
                <img
                  className="img-fluid border border-dark"
                  src={asset.sawaseed}
                  alt="logo"
                />
                <div className="fw-bolder">{t("instr4")}</div>
              </div>
              {capturedImageURL && (
                <div className="col text-center">
                  <img
                    className="img-fluid border border-dark"
                    src={capturedImageURL}
                    alt="logo"
                  />
                  <div className="fw-bolder">{t("instr5")}</div>
                </div>
              )}
            </div>
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="contained"
            sx={{ fontSize: "calc(.6rem + .2vw)", background: "#0F477E" }}
            onClick={() => navigate("/launchpage/englishactivity")}
          >
            {t("ok")}
          </Button>
        </Modal.Footer>
      </Modal>
      {/* compare modal eneds here */}
    </div>
  );
};

export default SawASeedMidContent_copy;
